  ["Convertir les m² comme les m (×10 au lieu de ×100)."],
  ("Citerne cylindrique : r = 1 m, h = 2 m. Volume en litres ?", ["V = π × 1² × 2 ≈ 6,28 m³.", "≈ 6 280 L."]),
